<section class="wsbiochips__s wsbiochips__s--bg"><div class="wsbiochips__v wsbiochips__dva wsbiochips__dva--rev"><div class="wsbiochips__media"><img src="<?php echo esc_url( get_template_directory_uri() . '/img/biochips/noriks-biochips-srebrna-1.webp' ); ?>" alt="Tehnologija koja ne slabi signal" loading="eager" decoding="async"></div><div><div class="wsbiochips__kicker">Znanost iza naljepnice</div><h2 class="wsbiochips__h2">Tehnologija koja <em>ne slabi signal</em></h2><p class="wsbiochips__p">NORIKS BioChips koristi tehnologiju koja je napravljena da umanji utjecaj EMF zračenja na tijelo – bez slabljenja veze uređaja, što su potvrdili testovi u američkom laboratoriju za RF izloženost.</p><ol class="wsbiochips__tocke"><li><span class="wsbiochips__st">01</span><div><strong>Održava sigurnu tjelesnu temperaturu</strong><p>Normalna tjelesna temperatura je oko 37 °C; već stupanj više znači vrućicu. Termografsko mjerenje pokazalo je manje zagrijavanje kože tijekom korištenja mobitela.</p></div></li><li><span class="wsbiochips__st">02</span><div><strong>Čuva zdrav pH</strong><p>Stanicama treba pravi pH da bi dobro radile. Laboratorijsko istraživanje na tehnološkom fakultetu u New Yorku mjerilo je stabilnost pH vode tijekom izloženosti mobitelu.</p></div></li><li><span class="wsbiochips__st">03</span><div><strong>Podržava rad mozga</strong><p>EMF može utjecati na ritam mozga, što se povezuje s lošijom koncentracijom i snom. Mali EEG pilot mjerio je promjene alfa-ritma – rezultati se razlikuju.</p></div></li></ol><div class="wsbiochips__red3"><div><span class="wsbiochips__pi"><svg viewBox="0 0 24 24" width="26" height="26" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M7.8 12.3l2.8 2.8 5.6-5.8"/></svg></span><strong>80,3 %</strong><span>promjena SAR-a</span></div><div><span class="wsbiochips__pi"><svg viewBox="0 0 24 24" width="26" height="26" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M7.8 12.3l2.8 2.8 5.6-5.8"/></svg></span><strong>Udobnost</strong><span>satima uz mobitel</span></div><div><span class="wsbiochips__pi"><svg viewBox="0 0 24 24" width="26" height="26" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 3l7.5 3v5.5c0 4.6-3.2 8.2-7.5 9.5-4.3-1.3-7.5-4.9-7.5-9.5V6z"/><path d="M8.6 12.2l2.4 2.4 4.4-4.6"/></svg></span><strong>Mir</strong><span>napredna zaštita</span></div></div></div></div></section>
<section class="wsbiochips__s"><div class="wsbiochips__v"><div class="wsbiochips__kicker wsbiochips__c">Najbolja upotreba</div><h2 class="wsbiochips__h2 wsbiochips__c">Gdje NORIKS BioChips <em>najviše koristi</em></h2><p class="wsbiochips__p wsbiochips__c">Naljepnica pristaje na svaki uređaj koji je blizu tijela – s maskicom ili bez nje.</p><div class="wsbiochips__grid wsbiochips__g4 wsbiochips__kar"><div class="wsbiochips__k"><div class="wsbiochips__km"><img src="<?php echo esc_url( get_template_directory_uri() . '/img/biochips/noriks-biochips-telefon.webp' ); ?>" alt="Mobitel" loading="eager" decoding="async"></div><div class="wsbiochips__kt"><strong>Mobitel</strong><p>Uz kameru na stražnjoj strani – uređaj koji nosite najbliže tijelu.</p></div></div><div class="wsbiochips__k"><div class="wsbiochips__km"><img src="<?php echo esc_url( get_template_directory_uri() . '/img/biochips/noriks-biochips-tablet.webp' ); ?>" alt="Tablet" loading="eager" decoding="async"></div><div class="wsbiochips__kt"><strong>Tablet</strong><p>Na poleđini tableta, i kod djece koja ga drže u krilu.</p></div></div><div class="wsbiochips__k"><div class="wsbiochips__km"><img src="<?php echo esc_url( get_template_directory_uri() . '/img/biochips/noriks-biochips-laptop.webp' ); ?>" alt="Laptop" loading="eager" decoding="async"></div><div class="wsbiochips__kt"><strong>Laptop</strong><p>Na poklopcu laptopa kad radite s njim na krilu.</p></div></div><div class="wsbiochips__k"><div class="wsbiochips__km"><img src="<?php echo esc_url( get_template_directory_uri() . '/img/biochips/noriks-biochips-konzola.webp' ); ?>" alt="Prijenosna igraća konzola s NORIKS zaslonom" loading="eager" decoding="async"></div><div class="wsbiochips__kt"><strong>Igraća konzola</strong><p>Na poleđini prijenosne konzole – za duge sate igranja u rukama.</p></div></div><div class="wsbiochips__k"><div class="wsbiochips__km"><img src="<?php echo esc_url( get_template_directory_uri() . '/img/biochips/noriks-biochips-citac.webp' ); ?>" alt="E-čitač u zelenoj maskici" loading="eager" decoding="async"></div><div class="wsbiochips__kt"><strong>E-čitač</strong><p>Na maskici čitača za duge večeri čitanja.</p></div></div></div></div></section>
<section class="wsbiochips__s wsbiochips__s--bg"><div class="wsbiochips__v wsbiochips__dva"><div class="wsbiochips__media" style="background:#000"><video src="<?php echo esc_url( get_template_directory_uri() . '/img/biochips/noriks-biochips-lijepljenje.mp4' ); ?>" poster="<?php echo esc_url( get_template_directory_uri() . '/img/biochips/noriks-biochips-lijepljenje.jpg' ); ?>" autoplay muted loop playsinline webkit-playsinline preload="metadata" aria-label="Animacija: NORIKS BioChips naljepnica se postavlja na stražnju stranu mobitela, uz kameru"></video></div><div><div class="wsbiochips__kicker">Uporaba</div><h2 class="wsbiochips__h2">Kako zalijepiti <em>u 4 koraka</em></h2><p class="wsbiochips__p">Postavljanje traje manje od minute i ne treba nikakav alat.</p><ol class="wsbiochips__tocke"><li><span class="wsbiochips__st">01</span><div><strong>Očistite površinu</strong><p>Stražnja strana uređaja mora biti čista, bez prašine i nečistoće.</p></div></li><li><span class="wsbiochips__st">02</span><div><strong>Pripremite naljepnicu</strong><p>Skinite zaštitnu foliju s naljepnice da otkrijete ljepljivu stranu.</p></div></li><li><span class="wsbiochips__st">03</span><div><strong>Postavite je</strong><p>Zalijepite naljepnicu u gornji desni kut stražnje strane mobitela, blizu kamere.</p></div></li><li><span class="wsbiochips__st">04</span><div><strong>Gotovo</strong><p>To je sve. Uređaj koristite kao i dosad – uz mir da je izloženost RF zračenju manja.</p></div></li></ol></div></div></section>
